import { test } from "node:test";
import assert from "node:assert/strict";
import { formatPrice } from "../src/utils.mjs";

test("formatPrice formatea números enteros", () => {
  assert.equal(formatPrice(10), "$10.00");
});

test("formatPrice formatea números con decimales", () => {
  assert.equal(formatPrice(10.5), "$10.50");
  assert.equal(formatPrice(10.55), "$10.55");
});

test("formatPrice redondea a dos decimales", () => {
  assert.equal(formatPrice(10.555), "$10.56");
});
